result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "counter.mjs", "content": "// Bates counter service — concurrent-safe contiguous range reservation.
//
// State lives in `<dir>/state.json`; mutual exclusion is provided by a
// mkdir-based exclusive lock directory with retry/backoff and stale-lock
// takeover after STALE_MS.

import { mkdir, readFile, writeFile, stat, rename, rmdir, rm } from 'node:fs/promises';
import { setTimeout as delay } from 'node:timers/promises';
import { randomBytes } from 'node:crypto';

export const STALE_MS = 2000;

const DEFAULT_LOCK_TIMEOUT_MS = 30_000;

function defaultDir() {
  return process.env.BATES_DATA_DIR || '.bates';
}

function sanitizePrefix(prefix) {
  return String(prefix).replace(/[^A-Za-z0-9._-]/g, '_');
}

/** Path of the exclusive lock directory for a prefix. */
export function lockPath(prefix, dir = defaultDir()) {
  return `${dir}/lock-${sanitizePrefix(prefix)}`;
}

function stateFile(dir) {
  return `${dir}/state.json`;
}

async function readState(dir) {
  try {
    const raw = await readFile(stateFile(dir), 'utf8');
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && parsed.counters) return parsed;
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }
  return { counters: {} };
}

async function writeState(dir, state) {
  await writeFile(stateFile(dir), JSON.stringify(state, null, 2));
}

/**
 * Acquire the exclusive lock directory for `prefix`.
 * Retries with randomized backoff; forcibly takes over a lock whose
 * directory mtime is older than STALE_MS (atomic rename steals it,
 * so exactly one contender can win).
 */
export async function acquireLock(prefix, {
  dir = defaultDir(),
  timeoutMs = DEFAULT_LOCK_TIMEOUT_MS,
} = {}) {
  const lp = lockPath(prefix, dir);
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      await mkdir(lp); // exclusive: fails with EEXIST if anyone holds it
      return lp;
    } catch (err) {
      if (err.code !== 'EEXIST') throw err;
      if (Date.now() > deadline) {
        throw new Error(`acquireLock: timed out waiting for lock ${lp}`);
      }
      // Locked — check for staleness.
      let st = null;
      try {
        st = await stat(lp);
      } catch {
        continue; // lock vanished between mkdir and stat; retry immediately
      }
      if (Date.now() - st.mtimeMs > STALE_MS) {
        // Atomic steal: only ONE contender's rename can succeed.
        const stolen = `${lp}.stolen.${process.pid}.${randomBytes(4).toString('hex')}`;
        try {
          await rename(lp, stolen);
          rm(stolen, { recursive: true, force: true }).catch(() => {});
          continue; // lock is now free; loop takes it
        } catch {
          // Lost the race (someone else stole it, or it was released).
        }
      }
      await delay(5 + Math.random() * 20); // backoff with jitter
    }
  }
}

/** Release a previously acquired lock directory (idempotent). */
export async function releaseLock(lp) {
  try {
    await rmdir(lp);
  } catch {
    /* already gone */
  }
}

/**
 * Reserve a contiguous, gap-free range of `count` numbers for `prefix`.
 * Returns `{ prefix, start, end }`. Safe across processes.
 */
export async function nextRange(prefix, count, {
  dir = defaultDir(),
  timeoutMs = DEFAULT_LOCK_TIMEOUT_MS,
} = {}) {
  if (!Number.isInteger(count) || count < 1) {
    throw new TypeError(`nextRange: count must be a positive integer, got ${count}`);
  }
  await mkdir(dir, { recursive: true }); // must exist before non-recursive lock mkdir
  const lp = await acquireLock(prefix, { dir, timeoutMs });
  try {
    const state = await readState(dir);
    const last = Number.isInteger(state.counters[prefix]) ? state.counters[prefix] : 0;
    const range = { prefix, start: last + 1, end: last + count };
    state.counters[prefix] = range.end;
    await writeState(dir, state);
    return range;
  } finally {
    await releaseLock(lp);
  }
}
"})
