result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "stamp.mjs", "content": "// Bates stamper — appends PREFIX-{n} footers (zero-padded to 7 digits)
// to every page of a text file, numbering pages contiguously via the
// concurrent-safe counter service.

import { readFile, writeFile } from 'node:fs/promises';
import { nextRange } from './counter.mjs';

export const PAD_WIDTH = 7;

/** Zero-pad a number to 7 digits: 42 -> "0000042". */
export function pad(n) {
  return String(n).padStart(PAD_WIDTH, '0');
}

/** Footer label: ("ACME", 42) -> "ACME-0000042". */
export function footer(prefix, n) {
  return `${prefix}-${pad(n)}`;
}

/**
 * Pure function: stamp `text`, assigning consecutive numbers starting at
 * `start`. Pages are delimited by form feed (\f); each page gets a
 * `PREFIX-{n}` footer line.
 */
export function stampText(text, prefix, start) {
  if (!Number.isInteger(start) || start < 1) {
    throw new TypeError(`stampText: start must be a positive integer, got ${start}`);
  }
  let n = start;
  return text
    .split('\f')
    .map((page) => `${page.replace(/\r?\n*$/, '')}\n${footer(prefix, n++)}`)
    .join('\f');
}

/**
 * Stamp a file in place: reserves as many numbers as the file has pages
 * (via nextRange) and rewrites it with footers.
 * Returns `{ start, end }`.
 */
export async function stampFile(filePath, prefix, { dir, timeoutMs } = {}) {
  const text = await readFile(filePath, 'utf8');
  const pageCount = text.split('\f').length;
  const { start, end } = await nextRange(prefix, pageCount, { dir, timeoutMs });
  await writeFile(filePath, stampText(text, prefix, start));
  return { start, end };
}
"})
