test(`concurrent reservation: ${WORKERS} workers x ${PAGES_PER_WORKER} pages are unique, contiguous, gap-free`, async () => {
  const dir = await tmpDir();
  const data = path.join(dir, 'data');

  const workerScript = `
    import { nextRange } from ${JSON.stringify(pathToFileURL(COUNTER_MJS).href)};
    const range = await nextRange(${JSON.stringify('DOC')}, ${PAGES_PER_WORKER}, {
      dir: ${JSON.stringify(data)},
