  const results = await Promise.all(
    Array.from({ length: WORKERS }, (_, i) =>
      runNode(workerScript, {}, `${dir}/worker-${i}.log`)
    )
  );

  const ranges = results.map((out) => JSON.parse(out.trim()));
  assert.equal(ranges.length, WORKERS);

  const issued = [];
  for (const r of ranges) {
    assert.equal(typeof r.start, 'number');
    assert.equal(typeof r.end, 'number');
    // Each individual reservation is contiguous.
    for (let n = r.start; n <= r.end; n++) issued.push(n);
  }

  assert.equal(issued.length, WORKERS * PAGES_PER_WORKER);

  // Unique...
  assert.equal(new Set(issued).size, issued.length, 'numbers must be unique');

  // Contiguous from 1 and gap-free: sorting must reproduce exactly 1..400.
  const sorted = [...issued].sort((a, b) => a - b);
  const expected = Array.from({ length: issued.length }, (_, i) => i + 1);
  assert.deepEqual(sorted, expected);

  // State on disk agrees.
  const state = JSON.parse(await readFile(path.join(data, 'state.json'), 'utf8'));
  assert.equal(state.counters.DOC, issued.length);
});

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

function runNode(script, env = {}, logFile = undefined) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ['--input-type=module', '-e', script], {
      cwd: tmpRoot,
      env: { ...process.env, ...env },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let out = '';
    let err = '';
    child.stdout.on('data', (d) => (out += d));
    child.stderr.on('data', (d) => (err += d));
    child.on('error', reject);
    child.on('close', (code) => {
      if (code === 0) resolve(out);
      else reject(new Error(`worker exited ${code}\nstdout: ${out}\nstderr: ${err}`));
    });
    if (logFile) {
      child.stderr.pipe((await import('node:fs')).createWriteStream(logFile));
    }
  });
}

let tmpRoot; // eslint-disable-line
